#!/usr/bin/env python3
"""rummy records サイト共通部品（フェーズ2で一本化）。

旧4ジェネレータに重複していた部品の単一の置き場所。
文字列は旧ジェネレータの実物から機械抽出したもので、生成HTMLが
従来とバイト単位で一致することを検証済み。

- NAV_HTML: ハンバーガーボタン＋ナビパネル（全ページ共通）
- MORPH_JS: メニューのモーフアニメーションJS中核（全ページ共通）
- navjs(): compact 3ページ（index/news/about）用のナビJS
- YEARJS: 年チップの sticky 検知JS（index/news 共通）
- FOOTER_HTML: SNS行フッター（全ページ共通）
- CSS_* （compact系）: index/news/about で共通のCSS断片
- NAVBTN_STYLE_OVERRIDE / style_tag(): <style> 末尾の navbtn 上書き
※ リリースページの CSS 本体も compact 書式に統一のうえ CSS_RELEASE_* として
  本モジュールに統合済み（フェーズ3準備・2026-11-25。検証は空白除去比較で差分ゼロ）。
"""
import html


def esc(s):
    return html.escape(s, quote=True)

NAV_HTML = '\n  <button class="navbtn" id="navbtn" aria-label="メニュー" aria-expanded="false">\n    <svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"><path class="mb-m" d="M4 7 L7.2 7 L10.4 7 L13.6 7 L16.8 7 L20 7 Z"/><path class="mb-m" d="M4 12 L7.2 12 L10.4 12 L13.6 12 L16.8 12 L20 12 Z"/><path class="mb-m" d="M4 17 L7.2 17 L10.4 17 L13.6 17 L16.8 17 L20 17 Z"/><path class="mb-in" stroke-width="0.5" d="M11.32 6.16 L15 8 L18.68 6.16 M15 8 L15 10.16" opacity="0"/><path class="mb-in" stroke-width="0.5" d="M4.92 11.56 L8.6 13.4 L12.28 11.56 M8.6 13.4 L8.6 15.56" opacity="0"/><path class="mb-in" stroke-width="0.5" d="M11.32 16.96 L15 18.8 L18.68 16.96 M15 18.8 L15 20.96" opacity="0"/></svg>\n  </button>\n  <nav class="navpanel" id="navpanel" aria-hidden="true">\n    <a href="index.html">Discography</a>\n    <a href="about.html">About us</a>\n    <a href="news.html">NEWS</a>\n  </nav>\n'

MORPH_JS = "    var mbPaths = navbtn ? navbtn.querySelectorAll('.mb-m') : [];\n    var mbIn = navbtn ? navbtn.querySelectorAll('.mb-in') : [];\n    var LINES = [7, 12, 17].map(function (y) { return [4, 7.2, 10.4, 13.6, 16.8, 20].map(function (x) { return [x, y]; }); });\n    function tilePts(cx, cy) { return [[cx - 4.6, cy - 0.9], [cx, cy - 3.2], [cx + 4.6, cy - 0.9], [cx + 4.6, cy + 1.8], [cx, cy + 4.1], [cx - 4.6, cy + 1.8]]; }\n    var TILES = [tilePts(15, 6.6), tilePts(8.6, 12), tilePts(15, 17.4)];\n    var mbT = 0, mbAnim = null;\n    function mbRender(t) {\n      for (var i = 0; i < 3; i++) {\n        var p = Math.min(1, Math.max(0, t * 1.24 - i * 0.12));\n        var e = p < .5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;\n        var d = '';\n        for (var k = 0; k < 6; k++) {\n          var x = LINES[i][k][0] + (TILES[i][k][0] - LINES[i][k][0]) * e;\n          var y = LINES[i][k][1] + (TILES[i][k][1] - LINES[i][k][1]) * e;\n          d += (k ? ' L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);\n        }\n        if (mbPaths[i]) { mbPaths[i].setAttribute('d', d + ' Z'); mbPaths[i].setAttribute('stroke-width', (1.3 - 0.8 * e).toFixed(2)); }\n        if (mbIn[i]) mbIn[i].setAttribute('opacity', Math.min(1, Math.max(0, (p - 0.55) / 0.45)).toFixed(2));\n      }\n    }\n    function mbMorph(open) {\n      if (!mbPaths.length) return;\n      if (mbAnim) cancelAnimationFrame(mbAnim);\n      var from = mbT, to = open ? 1 : 0, start = null;\n      function step(ts) {\n        if (!start) start = ts;\n        var raw = Math.min(1, (ts - start) / 420);\n        mbT = from + (to - from) * raw;\n        mbRender(mbT);\n        if (raw < 1) mbAnim = requestAnimationFrame(step); else mbAnim = null;\n      }\n      mbAnim = requestAnimationFrame(step);\n    }"

_NAVJS_PRE = "\n<script>\n  (function () {\n    var navbtn = document.getElementById('navbtn');\n    var navpanel = document.getElementById('navpanel');\n    if (!navbtn || !navpanel) return;\n    navbtn.addEventListener('click', function (e) {\n      e.stopPropagation();\n      var open = navpanel.classList.toggle('open'); mbMorph(open);\n      navbtn.setAttribute('aria-expanded', open ? 'true' : 'false');\n      navpanel.setAttribute('aria-hidden', open ? 'false' : 'true');\n    });\n    document.addEventListener('click', function (e) {\n      if (!navpanel.contains(e.target)) {\n        navpanel.classList.remove('open'); mbMorph(false);\n        navbtn.setAttribute('aria-expanded', 'false');\n        navpanel.setAttribute('aria-hidden', 'true');\n      }\n    });\n\n"

_NAVJS_POST = '\n  })();\n</script>\n'

YEARJS = "\n<script>\n  (function () {\n    if (!('IntersectionObserver' in window)) return;\n    document.querySelectorAll('.year').forEach(function (y) {\n      var s = document.createElement('div');\n      s.style.cssText = 'height:1px;margin-bottom:-1px;';\n      y.parentNode.insertBefore(s, y);\n      new IntersectionObserver(function (e) {\n        y.classList.toggle('stuck', !e[0].isIntersecting);\n      }, { rootMargin: '-9px 0px 0px 0px' }).observe(s);\n    });\n  })();\n</script>\n"

FOOTER_HTML = '  <footer>\n    <div class="snsrow">\n      <a href="https://rummyrecords.bandcamp.com/" aria-label="Bandcamp"><img src="https://cdn.simpleicons.org/bandcamp" alt="Bandcamp" width="26" height="26"></a>\n      <a href="https://x.com/rummyrecords" aria-label="X (Twitter)"><img class="xicon" src="https://cdn.simpleicons.org/x" alt="X (Twitter)" width="26" height="26"></a>\n      <a href="https://soundcloud.com/rummy-records" aria-label="SoundCloud"><img src="https://cdn.simpleicons.org/soundcloud" alt="SoundCloud" width="26" height="26"></a>\n      <a href="https://www.youtube.com/@rummyrecords" aria-label="YouTube"><img src="https://cdn.simpleicons.org/youtube" alt="YouTube" width="26" height="26"></a>\n    </div>\n  </footer>'

CSS_HEAD = '\n  :root { --bg:#C6CED4; --ink:#000; --accent:#C67223; --muted:#454b50;\n    --line:rgba(255,255,255,.55); --line-dark:rgba(70,80,88,.14); --glass:rgba(255,255,255,.65); }\n  * { box-sizing:border-box; margin:0; padding:0; }\n  body { min-height:100vh; background:var(--bg); color:var(--ink);\n    font-family:"Hiragino Kaku Gothic ProN","Hiragino Sans",system-ui,-apple-system,"Segoe UI",sans-serif;\n    line-height:1.6; display:flex; flex-direction:column; align-items:center; padding:40px 16px 48px; }\n  .label { text-decoration:none; color:var(--ink); font-family:Georgia,"Times New Roman","Hiragino Mincho ProN","Yu Mincho",serif;\n    font-size:19px; letter-spacing:.22em; text-align:center; margin-bottom:8px; padding-left:.22em;\n    text-shadow:0 -1px 1px rgba(255,255,255,.45), 0 2px 5px rgba(40,50,60,.28), 0 12px 24px rgba(40,50,60,.32); }\n  .sub { text-align:center; color:var(--muted); font-size:12px; letter-spacing:.3em; margin-bottom:22px; }\n'

CSS_SNS = '  .snsrow { display:flex; gap:20px; align-items:center; justify-content:center; }\n  .snsrow a { display:inline-flex; line-height:0; }\n  .snsrow img { width:26px; height:26px; display:block; }\n  .snsrow img.xicon { width:20px; height:20px; }\n  .snsrow a:hover { opacity:.65; }\n'

CSS_NAV = '  .navbtn { position:fixed; top:8px; right:12px; z-index:30; width:46px; height:46px; border-radius:14px;\n    display:flex; align-items:center; justify-content:center; background:rgba(255,255,255,.10); border:1px solid var(--line);\n    -webkit-backdrop-filter:blur(14px) saturate(1.2); backdrop-filter:blur(14px) saturate(1.2);\n    box-shadow:0 6px 18px rgba(40,50,60,.18), inset 0 1px 0 rgba(255,255,255,.65); cursor:pointer; color:var(--ink); }\n  .navpanel { position:fixed; top:62px; right:12px; z-index:30; min-width:190px; padding:8px;\n    background:var(--glass); border:1px solid var(--line); border-radius:14px;\n    -webkit-backdrop-filter:blur(14px) saturate(1.2); backdrop-filter:blur(14px) saturate(1.2);\n    box-shadow:0 12px 30px rgba(40,50,60,.25), inset 0 1px 0 rgba(255,255,255,.65);\n    display:flex; flex-direction:column; opacity:0; transform:translateY(-6px); pointer-events:none;\n    transition:opacity .18s ease, transform .18s ease; }\n  .navpanel.open { opacity:1; transform:translateY(0); pointer-events:auto; }\n  .navpanel a { padding:10px 12px; border-radius:9px; color:var(--ink); text-decoration:none; font-size:14px; font-weight:600; text-transform:uppercase; }\n  .navpanel a:hover { background:rgba(255,255,255,.55); color:var(--accent); }\n'

CSS_DARK_GLOW = '    .label { position:relative; z-index:0; color:#000; text-shadow:0 0 8px rgba(255,244,226,1), 0 0 22px rgba(255,226,180,.95), 0 0 48px rgba(252,206,140,.85), 0 2px 2px rgba(0,0,0,.35), 0 6px 12px rgba(0,0,0,.30); }\n    .label::before { content:"rummy records"; position:absolute; left:50%; top:50%; transform:translate(-50%,-50%) scale(1.12); white-space:nowrap; color:rgba(255,248,238,1); text-shadow:0 0 18px rgba(255,242,224,1), 0 0 50px rgba(255,238,212,1), 0 0 120px rgba(255,230,195,1), 0 0 200px rgba(255,222,180,.85), 0 0 280px rgba(255,214,168,.55); pointer-events:none; z-index:-1; filter:blur(20px) brightness(3.0); }\n    .label::after { content:""; position:absolute; left:50%; top:50%; width:min(170%, 92vw); height:340%; transform:translate(-50%,-50%); background:radial-gradient(ellipse at center, rgba(27,32,37,.85) 0%, rgba(27,32,37,.50) 45%, rgba(27,32,37,0) 72%); opacity:0; pointer-events:none; z-index:-1; will-change:opacity; }\n    @keyframes labeldim {\n      0% { opacity:0; }\n      35% { opacity:.5; }\n      100% { opacity:0; }\n    }\n    @media (hover:hover) {\n      .label:hover::after { animation:labeldim 1s ease; }\n    }\n    .card { box-shadow:0 12px 34px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.14); }\n    .navbtn { box-shadow:none; }\n    .navpanel { box-shadow:0 12px 30px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.14); }\n    .navpanel a:hover { background:rgba(255,255,255,.10); }\n    .snsrow img.xicon { content:url("https://cdn.simpleicons.org/x/white"); }\n    footer, footer a { color:#9AA5AD; }\n'

